JsonDict = Dict[str, Any]


def _sqlite_request_digest(value: object) -> str | None:
    """Hash one canonical operation request for trigger-side proof checks."""

    if not isinstance(value, str):
        return None
    try:
        parsed = json.loads(value)
        if canonical_json_bytes(parsed).decode("utf-8") != value:
            return None
        return request_digest(parsed)
    except (TypeError, ValueError, json.JSONDecodeError):
        return None


def _sqlite_catalog_paths_overlap(left: object, right: object) -> int:
    if not isinstance(left, str) or not isinstance(right, str):
        return 0
    return int(catalog_paths_overlap(left, right))


