@dataclass(frozen=True)
class WorkspaceAssemblyAttemptClaim:
    """One durable composer claim or a follower view of that exact claim."""

    attempt_id: str
    store_id: str
    change: OwnerChange
    composer: bool

    def __post_init__(self) -> None:
        required_text(
            self.attempt_id,
            "workspace assembly attempt id",
            max_bytes=512,
        )
        required_text(
            self.store_id,
            "workspace assembly attempt store id",
            max_bytes=128,
        )
        if not isinstance(self.change, OwnerChange):
            raise TypeError("workspace assembly attempt change is invalid.")
        if self.change.state is not OwnerChangeState.ACTIVE:
            raise ValueError("workspace assembly attempt change must be active.")
        if not isinstance(self.composer, bool):
            raise TypeError("workspace assembly composer flag must be a boolean.")

    @property
    def change_id(self) -> str:
        return self.change.change_id

    @property
    def owner_id(self) -> str:
        return self.change.owner_id

    def to_dict(self) -> JsonDict:
        return {
            "attempt_id": self.attempt_id,
            "change": self.change.to_dict(),
            "composer": self.composer,
            "store_id": self.store_id,
        }

    @classmethod
    def from_dict(cls, value: Mapping[str, Any]) -> "WorkspaceAssemblyAttemptClaim":
        try:
            if (
                set(value)
                - {
                    "attempt_id",
                    "change",
                    "composer",
                    "receipt_version",
                    "store_id",
                }
                or value.get("receipt_version", 1) != 1
            ):
                raise ValueError("workspace assembly attempt claim has invalid fields.")
            result = cls(
                attempt_id=value["attempt_id"],
                store_id=value["store_id"],
                change=OwnerChange.from_dict(value["change"]),
                composer=value["composer"],
            )
        except (KeyError, TypeError, ValueError) as error:
            raise RealmIntegrityError(
                "Workspace assembly attempt claim is malformed."
            ) from error
        canonical_value = dict(value)
        canonical_value.pop("receipt_version", None)
        if result.to_dict() != canonical_value:
            raise RealmIntegrityError(
                "Workspace assembly attempt claim is not canonical."
            )
        return result


