@dataclass(frozen=True)
class RunSelectionCapabilityFacts:
    """Exact-head, action-independent facts for one retained run selection.

    ``content`` describes direct byte inspection, while ``tree`` describes the
    stricter derivable-tree authority required by Keep. Candidate
    semantics are present only when the actor can derive the retained runnable
    closure. These facts are advisory presentation input: every action still
    resolves the immutable selection again at execution time.
    """

    selection: SelectionRef
    content: ResolvedSelectionContent
    tree: ResolvedSelection
    candidate_target: ResolvedCandidateInspectionTarget | None

    def __post_init__(self) -> None:
        if not isinstance(self.selection, SelectionRef):
            raise TypeError("selection must be a SelectionRef.")
        if not isinstance(self.content, ResolvedSelectionContent):
            raise TypeError("content must be a ResolvedSelectionContent.")
        if not isinstance(self.tree, ResolvedSelection):
            raise TypeError("tree must be a ResolvedSelection.")
        if (
            self.content.selection != self.selection
            or self.tree.selection != self.selection
        ):
            raise ValueError(
                "selection capability facts identify different selections."
            )
        if (
            self.content.source_current_owner_revision
            != self.tree.source_current_owner_revision
        ):
            raise ValueError("selection capability facts differ at the owner head.")
        if self.candidate_target is not None:
            if not isinstance(self.candidate_target, ResolvedCandidateInspectionTarget):
                raise TypeError(
                    "candidate_target must be a ResolvedCandidateInspectionTarget or None."
                )
            if self.candidate_target.selection != self.selection:
                raise ValueError("candidate target identifies another selection.")


@dataclass(frozen=True)
class StoreRecord:
    store_id: str
    backend_kind: str
    root_marker: str
    state: str
    created_at: float

    def __post_init__(self) -> None:
        required_text(self.store_id, "store_id", max_bytes=128)
        required_text(self.backend_kind, "backend kind", max_bytes=128)
        required_text(self.root_marker, "root marker")
        if self.state not in {"active", "degraded", "disabled"}:
            raise ValueError("store state is invalid.")
        object.__setattr__(
            self, "created_at", finite_time(self.created_at, "store created_at")
        )

    def to_dict(self) -> JsonDict:
        return {
            "store_id": self.store_id,
            "backend_kind": self.backend_kind,
            "root_marker": self.root_marker,
            "state": self.state,
            "created_at": self.created_at,
        }

    @classmethod
    def from_dict(cls, value: Mapping[str, Any]) -> "StoreRecord":
        try:
            return cls(
                store_id=value["store_id"],
                backend_kind=value["backend_kind"],
                root_marker=value["root_marker"],
                state=value["state"],
                created_at=value["created_at"],
            )
        except (KeyError, TypeError, ValueError) as error:
            raise RealmIntegrityError("Persisted store record is malformed.") from error


