@dataclass(frozen=True)
class ContentRecord:
    store_id: str
    content_ref: PhysicalContentRef
    kind: str
    logical_bytes: int
    physical_bytes: int
    lifecycle_state: str
    trust_state: str
    metadata: Mapping[str, Any]
    created_at: float
    verified_at: float

    def __post_init__(self) -> None:
        required_text(self.store_id, "store_id", max_bytes=128)
        expected_kind = _content_kind(self.content_ref)
        if self.kind != expected_kind:
            raise ValueError("content kind does not match its reference.")
        nonnegative_int(self.logical_bytes, "logical_bytes")
        nonnegative_int(self.physical_bytes, "physical_bytes")
        if self.lifecycle_state not in {
            "live",
            "tombstoned",
            "deleting",
            "deleted",
            "corrupt",
            "quarantined",
        }:
            raise ValueError("content lifecycle state is invalid.")
        if self.trust_state not in {"verified_local", "unverified", "corrupt"}:
            raise ValueError("content trust state is invalid.")
        created = finite_time(self.created_at, "content created_at")
        verified = finite_time(self.verified_at, "content verified_at")
        if verified < created:
            raise ValueError("content verified_at must not precede created_at.")
        object.__setattr__(self, "created_at", created)
        object.__setattr__(self, "verified_at", verified)
        object.__setattr__(
            self, "metadata", freeze_json(self.metadata, label="content metadata")
        )

    def to_dict(self) -> JsonDict:
        return {
            "store_id": self.store_id,
            "content_ref": str(self.content_ref),
            "kind": self.kind,
            "logical_bytes": self.logical_bytes,
            "physical_bytes": self.physical_bytes,
            "lifecycle_state": self.lifecycle_state,
            "trust_state": self.trust_state,
            "metadata": thaw_json(self.metadata),
            "created_at": self.created_at,
            "verified_at": self.verified_at,
        }

    @classmethod
    def from_dict(cls, value: Mapping[str, Any]) -> "ContentRecord":
        try:
            return cls(
                store_id=value["store_id"],
                content_ref=parse_physical_content_ref(value["content_ref"]),
                kind=value["kind"],
                logical_bytes=value["logical_bytes"],
                physical_bytes=value["physical_bytes"],
                lifecycle_state=value["lifecycle_state"],
                trust_state=value["trust_state"],
                metadata=value.get("metadata", {}),
                created_at=value["created_at"],
                verified_at=value["verified_at"],
            )
        except (KeyError, TypeError, ValueError) as error:
            raise RealmIntegrityError(
                "Persisted content record is malformed."
            ) from error


