    def commit_run_attempt_terminal_evidence(
        self,
        *,
        operation_id: str,
        actor_principal_id: str,
        run_id: str,
        attempt_id: str,
        binding_id: str,
        launch_token: str,
        provider_kind: str,
        evidence_fingerprint: str,
        launch_request_digest: str,
        proof_fingerprint: str,
        started: bool,
        disposition: str,
    ) -> ExecutionTerminalEvidenceRecord:
        """Retain path-free terminal evidence after provider proof validation.

        Provider-private proof bytes and backend tokens are intentionally not
        accepted by this metadata API.  The execution binder validates that
        proof first, then commits only its fingerprint and exact launch chain.
        """

        operation_id = _text(operation_id, "operation_id")
        actor_principal_id = _text(actor_principal_id, "actor principal_id")
        run_id = _bounded_text(run_id, "run id", max_bytes=512)
        attempt_id = _bounded_text(attempt_id, "attempt id", max_bytes=512)
        binding_id = _bounded_text(binding_id, "binding id", max_bytes=512)
        launch_token = _bounded_text(launch_token, "launch token", max_bytes=512)
        provider_kind = _bounded_text(
            provider_kind, "execution provider kind", max_bytes=128
        )
        evidence_fingerprint = lower_hex_digest(
            evidence_fingerprint, "execution binding evidence fingerprint"
        )
        launch_request_digest = lower_hex_digest(
            launch_request_digest, "execution launch request digest"
        )
        proof_fingerprint = lower_hex_digest(
            proof_fingerprint, "execution terminal proof fingerprint"
        )
        if not isinstance(started, bool):
            raise TypeError("started must be a boolean.")
        disposition = _bounded_text(
            disposition, "execution terminal disposition", max_bytes=32
        )
        if disposition not in {"never_started", "exited", "killed"}:
            raise ValueError("execution terminal disposition is unsupported.")
        if started != (disposition != "never_started"):
            raise ValueError("started differs from terminal disposition.")
        expected_operation_id = run_attempt_terminal_evidence_operation_id(
            actor_principal_id=actor_principal_id,
            run_id=run_id,
            attempt_id=attempt_id,
            binding_id=binding_id,
            proof_fingerprint=proof_fingerprint,
        )
        if operation_id != expected_operation_id:
            raise ValueError(
                "terminal evidence operation_id differs from its exact coordinate."
            )
        request = {
            "actor_principal_id": actor_principal_id,
            "run_id": run_id,
            "attempt_id": attempt_id,
            "binding_id": binding_id,
            "launch_token": launch_token,
            "provider_kind": provider_kind,
            "evidence_fingerprint": evidence_fingerprint,
            "launch_request_digest": launch_request_digest,
            "proof_fingerprint": proof_fingerprint,
            "started": started,
            "disposition": disposition,
        }

        def body(
            connection: sqlite3.Connection, txn_id: int, now: float
        ) -> Mapping[str, Any]:
            run_row = connection.execute(
                "SELECT * FROM run_namespaces WHERE run_id = ?", (run_id,)
            ).fetchone()
            if run_row is None:
                raise _missing()
            owner = self._authorize_owner(
                connection,
                actor_principal_id=actor_principal_id,
                owner_id=run_row["owner_id"],
                permission=OwnerPermission.DERIVE,
            )
            self._require_active_owner(owner)
            attempt_row = connection.execute(
                "SELECT * FROM run_attempts WHERE run_id = ? AND attempt_id = ?",
                (run_id, attempt_id),
            ).fetchone()
            if attempt_row is None:
                raise _missing()
            binding = _execution_binding_from_rows(
                connection, run_id=run_id, attempt_id=attempt_id
            )
            launch = _execution_launch_intent_from_row(
                connection.execute(
                    "SELECT * FROM run_attempt_execution_launch_intents "
                    "WHERE run_id = ? AND attempt_id = ?",
                    (run_id, attempt_id),
                ).fetchone()
            )
            attempt = _run_attempt_from_row(attempt_row)
            launch.validate_binding(binding, attempt)
            if attempt.state == "running" and not started:
                raise RealmConflict(
                    "A confirmed-running attempt cannot have never-started evidence."
                )
            if (
                binding.binding_id != binding_id
                or attempt.binding_id != binding_id
                or attempt.launch_token != launch_token
                or launch.launch_token != launch_token
                or launch.provider_kind != provider_kind
                or launch.evidence_fingerprint != evidence_fingerprint
                or launch.launch_request_digest != launch_request_digest
            ):
                raise RealmConflict(
                    "Terminal evidence differs from the exact launch intent."
                )
            existing = connection.execute(
                "SELECT * FROM run_attempt_execution_terminal_evidence "
                "WHERE run_id = ? AND attempt_id = ?",
                (run_id, attempt_id),
            ).fetchone()
            if existing is not None:
                record = _execution_terminal_evidence_from_row(existing)
                if (
                    record.binding_id != binding_id
                    or record.launch_token != launch_token
                    or record.provider_kind != provider_kind
                    or record.evidence_fingerprint != evidence_fingerprint
                    or record.launch_request_digest != launch_request_digest
                    or record.proof_fingerprint != proof_fingerprint
                    or record.started != started
                    or record.disposition != disposition
                ):
                    raise RealmConflict(
                        "Terminal evidence was already committed differently."
                    )
                return record.to_dict()
            if (
                run_row["state"] != "running"
                or run_row["retention_state"] != "active"
                or attempt.state not in {"prepared", "running"}
            ):
                raise RealmConflict(
                    "Attempt no longer accepts execution terminal evidence."
                )
            connection.execute(
                "INSERT INTO run_attempt_execution_terminal_evidence("
                "run_id, attempt_id, binding_id, launch_token, provider_kind, "
                "evidence_fingerprint, launch_request_digest, proof_fingerprint, "
                "started, disposition, created_by_principal_id, created_txn_id, "
                "created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                (
                    run_id,
                    attempt_id,
                    binding_id,
                    launch_token,
                    provider_kind,
                    evidence_fingerprint,
                    launch_request_digest,
                    proof_fingerprint,
                    int(started),
                    disposition,
                    actor_principal_id,
                    txn_id,
                    now,
                ),
            )
            return _execution_terminal_evidence_from_row(
                connection.execute(
                    "SELECT * FROM run_attempt_execution_terminal_evidence "
                    "WHERE run_id = ? AND attempt_id = ?",
                    (run_id, attempt_id),
                ).fetchone()
            ).to_dict()

        return ExecutionTerminalEvidenceRecord.from_dict(
            self._operate(
                operation_id=operation_id,
                operation_kind="run.attempt.execution-terminal-evidence",
                request=request,
                body=body,
            )
        )

