def _run_observation_from_row(row: Optional[sqlite3.Row]) -> RunObservationRecord:
    if row is None:
        raise _missing()
    try:
        envelope_value = _load_canonical_json_value(
            row["envelope_json"],
            "run observation envelope",
            require_mapping=True,
        )
        parsed = AttemptEnvelope.from_dict(envelope_value)
        projected = {
            "validation_json": parsed.validation,
            "materialization_json": parsed.materialization,
            "metric_values_json": parsed.metric_values,
            "constraint_results_json": parsed.constraint_results,
            "event_summary_json": parsed.event_summary,
            "execution_metadata_json": parsed.execution_metadata,
            "error_json": parsed.error,
        }
        for column, value in projected.items():
            if row[column] != canonical_json_bytes(_run_record_thaw(value)).decode(
                "utf-8"
            ):
                raise RealmIntegrityError(
                    "Persisted observation projection differs from its envelope."
                )
        if (
            row["envelope_digest"] != parsed.digest
            or row["status"] != parsed.outcome
            or row["phase"] != parsed.phase
            or float(row["wall_clock_seconds"]) != parsed.wall_clock_seconds
        ):
            raise RealmIntegrityError(
                "Persisted observation anchors differ from its envelope."
            )
        return RunObservationRecord(
            run_id=_text(row["run_id"], "run id"),
            observation_id=_text(row["observation_id"], "observation id"),
            attempt_id=_text(row["attempt_id"], "attempt id"),
            envelope=parsed,
            adopted_run_revision=_positive_int(
                row["adopted_run_revision"], "observation adopted run revision"
            ),
            adopted_sequence=_positive_int(
                row["adopted_sequence"], "observation adopted sequence"
            ),
            adopted_txn_id=_positive_int(
                row["adopted_txn_id"], "observation adopted transaction id"
            ),
            created_at=_finite_time(row["created_at"], "observation created_at"),
        )
    except RealmIntegrityError:
        raise
    except (KeyError, TypeError, ValueError) as error:
        raise RealmIntegrityError(
            "Persisted run observation row is malformed."
        ) from error


