def _workspace_selection(
    workspace: WorkspaceRecord,
    revision: WorkspaceRevision,
) -> SelectionRef:
    """Build the canonical portable action coordinate for one workspace revision."""

    if workspace.workspace_id != revision.workspace_id:
        raise RealmIntegrityError(
            "Workspace selection revision belongs to another workspace."
        )
    return SelectionRef.build(
        kind="workspace",
        source_kind="workspace",
        source_id=workspace.workspace_id,
        source_owner_id=workspace.owner_id,
        source_revision=revision.revision,
        owner_revision=revision.owner_revision,
        source_sequence=None,
        entity_sequence=None,
        entity_id=workspace.workspace_id,
        entity_ref=str(revision.root_ref),
        context_digest=request_digest(
            {
                "schema": "optpilot.workspace-selection-context.v1",
                "root_store_id": revision.root_store_id,
                "lineage": revision.lineage.to_dict(),
            }
        ),
    )


