def _path_free_execution_handle(value: Any, label: str) -> str:
    result = _bounded_text(value, label, max_bytes=512)
    if (
        "/" in result
        or "\\" in result
        or ":" in result
        or result.startswith((".", "~"))
    ):
        raise ValueError(f"{label} must be a path-free operational identifier.")
    return result


def _validate_execution_handle_shapes(
    projections: Tuple[ExecutionProjectionHandle, ...],
    volumes: Tuple[ExecutionVolumeHandle, ...],
) -> None:
    if not projections:
        raise ValueError("At least one execution projection is required.")
    projection_names = [item.logical_name for item in projections]
    volume_names = [item.logical_name for item in volumes]
    if len(set(projection_names)) != len(projection_names):
        raise ValueError("Execution projection logical names must be unique.")
    if len(set(volume_names)) != len(volume_names):
        raise ValueError("Execution volume logical names must be unique.")
    projection_ids = []
    projection_consumers = []
    authority_lease_ids = []
    volume_ids = []
    for item in projections:
        _path_free_execution_handle(item.provider_kind, "projection provider kind")
        projection_ids.append(
            _path_free_execution_handle(
                item.realization_id, "projection realization id"
            )
        )
        projection_consumers.append(
            _path_free_execution_handle(item.consumer_id, "projection consumer id")
        )
        authority_lease_ids.append(
            _path_free_execution_handle(
                item.consumer_lease_id, "projection consumer lease id"
            )
        )
    for item in volumes:
        _path_free_execution_handle(item.provider_kind, "volume provider kind")
        volume_ids.append(
            _path_free_execution_handle(item.volume_id, "ephemeral volume id")
        )
        authority_lease_ids.append(
            _path_free_execution_handle(
                item.usage_lease_id, "ephemeral volume usage lease id"
            )
        )
    for values, label in (
        (projection_ids, "projection realizations"),
        (projection_consumers, "projection consumers"),
        (volume_ids, "ephemeral volumes"),
        (authority_lease_ids, "execution authority leases"),
    ):
        if len(set(values)) != len(values):
            raise ValueError(f"{label} must be unique.")


def _authenticate_attempt_projection_sources(
    *,
    mappings: Sequence[TreeMapping],
    candidate_input: CandidateRuntimeInput,
    candidate_content_bindings: Sequence[OwnerMembership],
    store_id: str,
) -> Tuple[SnapshotRef, ...]:
    """Authenticate one attempt projection's exact semantic source set.

    Projection availability records canonicalize snapshot roots as a sorted set,
    while the runtime plan keeps ordered mappings because their destinations are
    semantic.  Validate the ordered environment/candidate mapping shape first,
    then return the provider's canonical root representation.  A file-candidate
    source is accepted only through the exact candidate selected by this attempt
    and a live ``RUN_CANDIDATE_ROLE`` placement in the selected store; retaining
    the same snapshot under another role is deliberately insufficient.
    """

    if isinstance(mappings, (str, bytes)) or not isinstance(mappings, Sequence):
        raise TypeError("runtime projection mappings must be a sequence.")
    mapping_values = tuple(mappings)
    if not mapping_values or any(
        not isinstance(item, TreeMapping) for item in mapping_values
    ):
        raise RealmIntegrityError("Runtime projection mappings are malformed.")
    if not isinstance(candidate_input, CandidateRuntimeInput):
        raise TypeError("candidate_input must be a CandidateRuntimeInput.")
    if isinstance(candidate_content_bindings, (str, bytes)) or not isinstance(
        candidate_content_bindings, Sequence
    ):
        raise TypeError("candidate_content_bindings must be a sequence.")
    binding_values = tuple(candidate_content_bindings)
    if any(not isinstance(item, OwnerMembership) for item in binding_values):
        raise TypeError(
            "candidate_content_bindings must contain OwnerMembership values."
        )
    store_id = _bounded_text(store_id, "projection store id", max_bytes=128)

    destinations = tuple(item.destination for item in mapping_values)
    has_prepared_python = (
        ENVIRONMENT_PREPARED_PYTHON_PARTITION in destinations
    )
    expected_base = (ENVIRONMENT_PROJECTION_PARTITION,)
    if has_prepared_python:
        expected_base += (ENVIRONMENT_PREPARED_PYTHON_PARTITION,)
    if any(
        item.source_subpath
        != (
            "site-packages"
            if item.destination == ENVIRONMENT_PREPARED_PYTHON_PARTITION
            else "."
        )
        for item in mapping_values
    ):
        raise RealmIntegrityError(
            "Runtime projection sources map unsupported immutable subtrees."
        )
    if candidate_input.candidate_format == "parameters":
        if destinations != expected_base or binding_values:
            raise RealmIntegrityError(
                "Parameter attempt projection sources differ from candidate authority."
            )
    elif candidate_input.candidate_format == "files":
        candidate_snapshot = candidate_input.snapshot_ref
        if not isinstance(candidate_snapshot, SnapshotRef):
            raise RealmIntegrityError(
                "File attempt candidate snapshot authority is malformed."
            )
        if destinations != expected_base + (CANDIDATE_PROJECTION_PARTITION,):
            raise RealmIntegrityError(
                "File attempt projection sources differ from candidate authority."
            )
        candidate_mapping = mapping_values[-1]
        if candidate_mapping.snapshot_ref != candidate_snapshot:
            raise RealmIntegrityError(
                "File attempt projection substituted its candidate snapshot."
            )
        if not binding_values or any(
            item.role != RUN_CANDIDATE_ROLE or item.content_ref != candidate_snapshot
            for item in binding_values
        ):
            raise RealmIntegrityError(
                "File attempt candidate bindings differ from candidate authority."
            )
        if not any(item.store_id == store_id for item in binding_values):
            raise RealmConflict(
                "File attempt candidate has no authorized placement in the projection store."
            )
    else:  # pragma: no cover - CandidateRuntimeInput validates its union
        raise RealmIntegrityError("Attempt candidate format is unsupported.")

    return tuple(sorted({item.snapshot_ref for item in mapping_values}, key=str))


def _execution_binding_from_rows(
    connection: sqlite3.Connection,
    *,
    run_id: str,
    attempt_id: str,
) -> ExecutionBindingRecord:
    row = connection.execute(
        "SELECT * FROM run_attempt_execution_bindings "
        "WHERE run_id = ? AND attempt_id = ?",
        (run_id, attempt_id),
    ).fetchone()
    if row is None:
        raise _missing()
    projection_rows = tuple(
        connection.execute(
            "SELECT * FROM run_attempt_execution_projections "
            "WHERE run_id = ? AND attempt_id = ? ORDER BY logical_name",
            (run_id, attempt_id),
        )
    )
    volume_rows = tuple(
        connection.execute(
            "SELECT * FROM run_attempt_execution_volumes "
            "WHERE run_id = ? AND attempt_id = ? ORDER BY logical_name",
            (run_id, attempt_id),
        )
    )
    return _execution_binding_from_record_rows(row, projection_rows, volume_rows)


def _execution_bindings_for_run_from_rows(
    connection: sqlite3.Connection,
    *,
    run_id: str,
) -> Tuple[ExecutionBindingRecord, ...]:
    """Load every binding and handle in three bounded snapshot queries."""

    binding_rows = tuple(
        connection.execute(
            "SELECT binding.* FROM run_attempt_execution_bindings binding "
            "JOIN run_attempts attempt "
            "ON attempt.run_id = binding.run_id "
            "AND attempt.attempt_id = binding.attempt_id "
            "JOIN run_logical_trials trial "
            "ON trial.run_id = attempt.run_id "
            "AND trial.logical_trial_id = attempt.logical_trial_id "
            "WHERE binding.run_id = ? "
            "ORDER BY trial.budget_slot, attempt.attempt_index",
            (run_id,),
        )
    )
    projection_groups: dict[str, list[sqlite3.Row]] = {}
    for row in connection.execute(
        "SELECT projection.* FROM run_attempt_execution_projections projection "
        "JOIN run_attempts attempt "
        "ON attempt.run_id = projection.run_id "
        "AND attempt.attempt_id = projection.attempt_id "
        "JOIN run_logical_trials trial "
        "ON trial.run_id = attempt.run_id "
        "AND trial.logical_trial_id = attempt.logical_trial_id "
        "WHERE projection.run_id = ? "
        "ORDER BY trial.budget_slot, attempt.attempt_index, "
        "projection.logical_name",
        (run_id,),
    ):
        projection_groups.setdefault(row["attempt_id"], []).append(row)
    volume_groups: dict[str, list[sqlite3.Row]] = {}
    for row in connection.execute(
        "SELECT volume.* FROM run_attempt_execution_volumes volume "
        "JOIN run_attempts attempt "
        "ON attempt.run_id = volume.run_id "
        "AND attempt.attempt_id = volume.attempt_id "
        "JOIN run_logical_trials trial "
        "ON trial.run_id = attempt.run_id "
        "AND trial.logical_trial_id = attempt.logical_trial_id "
        "WHERE volume.run_id = ? "
        "ORDER BY trial.budget_slot, attempt.attempt_index, volume.logical_name",
        (run_id,),
    ):
        volume_groups.setdefault(row["attempt_id"], []).append(row)
    return tuple(
        _execution_binding_from_record_rows(
            row,
            tuple(projection_groups.pop(row["attempt_id"], ())),
            tuple(volume_groups.pop(row["attempt_id"], ())),
        )
        for row in binding_rows
    )


def _execution_binding_from_record_rows(
    row: sqlite3.Row,
    projection_rows: Sequence[sqlite3.Row],
    volume_rows: Sequence[sqlite3.Row],
) -> ExecutionBindingRecord:
    try:
        spec_value = _load_canonical_json_value(
            row["portable_spec_json"],
            "portable attempt runtime spec",
            require_mapping=True,
        )
        evidence_value = _load_canonical_json_value(
            row["evidence_json"],
            "execution binding evidence",
            require_mapping=True,
        )
        spec = PortableAttemptRuntimeSpec.from_dict(spec_value)
        evidence = ExecutionBindingEvidence.from_dict(evidence_value)
        projection_handles = tuple(
            ExecutionProjectionHandle(
                logical_name=item["logical_name"],
                provider_kind=item["provider_kind"],
                realization_id=item["realization_id"],
                consumer_id=item["consumer_id"],
                consumer_lease_id=item["consumer_lease_id"],
                consumer_fencing_token=_positive_int(
                    item["consumer_fencing_token"],
                    "projection consumer fencing token",
                ),
            )
            for item in projection_rows
        )
        volume_handles = tuple(
            ExecutionVolumeHandle(
                logical_name=item["logical_name"],
                provider_kind=item["provider_kind"],
                volume_id=item["volume_id"],
                usage_lease_id=item["usage_lease_id"],
                usage_fencing_token=_positive_int(
                    item["usage_fencing_token"],
                    "ephemeral volume usage fencing token",
                ),
            )
            for item in volume_rows
        )
        _validate_execution_handle_shapes(projection_handles, volume_handles)
        result = ExecutionBindingRecord(
            run_id=row["run_id"],
            attempt_id=row["attempt_id"],
            binding_id=row["binding_id"],
            portable_spec=spec,
            evidence=evidence,
            projections=projection_handles,
            writable_volumes=volume_handles,
            resource_ttl_seconds=_positive_ttl(row["resource_ttl_seconds"]),
            created_run_revision=_positive_int(
                row["created_run_revision"], "binding created run revision"
            ),
            created_sequence=_positive_int(
                row["created_sequence"], "binding created sequence"
            ),
            created_txn_id=_positive_int(
                row["created_txn_id"], "binding created transaction"
            ),
            created_at=_finite_time(row["created_at"], "binding created_at"),
        )
        if (
            row["portable_spec_json"]
            != canonical_json_bytes(spec.to_dict()).decode("utf-8")
            or row["portable_spec_digest"] != spec.digest
            or row["evidence_json"]
            != canonical_json_bytes(evidence.to_dict()).decode("utf-8")
            or row["evidence_fingerprint"] != evidence.fingerprint
            or row["run_definition_digest"] != spec.run_definition_digest
        ):
            raise RealmIntegrityError(
                "Persisted execution binding digests do not agree."
            )
        return result
    except RealmIntegrityError:
        raise
    except (KeyError, TypeError, ValueError) as error:
        raise RealmIntegrityError(
            "Persisted execution binding record is malformed."
        ) from error


